Evaluate the following SQLite query exactly. Use each row key as the field and its integer value as the result. No explanation is needed.
WITH readings(g,v) AS (
  VALUES ('P',NULL),('P',4),('P',4),('Q',NULL),('Q',NULL),('R',7),('R',8),('R',8)
)
SELECT g, COUNT(DISTINCT v) FROM readings GROUP BY g ORDER BY g;
Return the following fields with one value each: P, Q, R.

Evaluate the following SQLite query exactly. Use each row key as the field and its integer value as the result. No explanation is needed.
WITH items(g,seq,t,v) AS (
  VALUES ('P',11,9,4),('P',12,9,8),('P',13,8,3),
         ('Q',21,4,6),('Q',22,5,9),('Q',23,5,1),
         ('R',31,2,7),('R',32,2,2),('R',33,1,3)
), eligible AS (
  SELECT * FROM items WHERE v >= 3
), ranked AS (
  SELECT g, seq, ROW_NUMBER() OVER (PARTITION BY g ORDER BY t DESC, seq DESC) AS rn
  FROM eligible
)
SELECT g, seq FROM ranked WHERE rn = 1 ORDER BY g;
Return the following fields with one value each: P, Q, R.
